
CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,phone TEXT,password_hash TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE properties(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,name TEXT NOT NULL,address TEXT NOT NULL,property_type TEXT DEFAULT 'Residential',notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE units(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,property_id INTEGER NOT NULL,unit_name TEXT NOT NULL,rent_amount REAL NOT NULL DEFAULT 0,status TEXT DEFAULT 'vacant',notes TEXT);
CREATE TABLE tenants(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,full_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,national_id TEXT,next_of_kin TEXT,next_of_kin_phone TEXT,address TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE leases(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,tenant_id INTEGER NOT NULL,unit_id INTEGER NOT NULL,start_date TEXT NOT NULL,end_date TEXT,monthly_rent REAL NOT NULL,due_day INTEGER DEFAULT 1,deposit_amount REAL DEFAULT 0,status TEXT DEFAULT 'active',notes TEXT);
CREATE TABLE payments(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,lease_id INTEGER NOT NULL,amount REAL NOT NULL,payment_date TEXT NOT NULL,period_month TEXT NOT NULL,method TEXT DEFAULT 'cash',reference_no TEXT,received_by TEXT,notes TEXT);
CREATE TABLE expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,property_id INTEGER,expense_date TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,amount REAL NOT NULL,paid_to TEXT);
CREATE TABLE maintenance_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,unit_id INTEGER,tenant_id INTEGER,title TEXT NOT NULL,description TEXT,priority TEXT DEFAULT 'normal',status TEXT DEFAULT 'open',request_date TEXT NOT NULL,cost REAL DEFAULT 0);
CREATE INDEX ix_prop_user ON properties(user_id); CREATE INDEX ix_units_user ON units(user_id); CREATE INDEX ix_tenant_user ON tenants(user_id); CREATE INDEX ix_lease_user ON leases(user_id); CREATE INDEX ix_pay_user_month ON payments(user_id,period_month); CREATE INDEX ix_exp_user ON expenses(user_id);
